#!/bin/bash
# ref against shared objects in code generated by gortc (bench/gortc/refcount.gort), and the same program built with --atomic-refs.
# usage: run_gortc_refcount.sh [reps]   writes results/gortc_refcount.txt and results/gortc_refcount.md
D=$(dirname "$0"); R=${1:-7}; BIN=${TMPDIR:-/tmp}/gortc_rc; mkdir -p "$BIN"
GC="$D/../gortc/target/release/gortc"; (cd "$D/../gortc" && cargo build --release -q) || exit 1
export GORTC_OPT=-O2
"$GC" build -o "$BIN/plain" "$D/gortc/refcount.gort" || exit 1
"$GC" build --atomic-refs -o "$BIN/atomic" "$D/gortc/refcount.gort" || exit 1
OUT="$D/results/gortc_refcount.txt"; : > "$OUT"
for rep in $(seq "$R"); do
  for cfg in plain atomic; do
    taskset -c 2 "$BIN/$cfg" | sed "s/^/$cfg /" >> "$OUT"
  done
done
python3 - "$OUT" > "$D/results/gortc_refcount.md" <<'PY'
import sys, statistics, collections
d = collections.defaultdict(list)
for l in open(sys.argv[1]):
    p = l.split()
    if len(p) == 4: d[(p[0], p[1], p[2])].append(int(p[3]))
print("Median picoseconds per iteration, gortc output, `-O2`, one thread pinned to one core.\n")
print("| workload | ref | shared | ref built with --atomic-refs | shared / ref |\n|---|---|---|---|---|")
for w in ["store", "sync", "alloc", "list"]:
    r = statistics.median(d[("plain", w, "ref")]); s = statistics.median(d[("plain", w, "shared")]); a = statistics.median(d[("atomic", w, "ref")])
    print(f"| {w} | {r:.0f} | {s:.0f} | {a:.0f} | {s / max(r, 1):.1f}x |")
PY
cat "$D/results/gortc_refcount.md"
